effect.shader:
#define iTime (0.0)
#define iResolution vec3(acScreenSize, 1.0)
#define iDate vec4(0.0, 0.0, 0.0, iTime)
#define iMouse vec4(acScreenSize * 0.5, 0.0, 0.0)
void gmGeneratedMainImage(out vec4 fragColor, in vec2 fragCoord)
{
vec2 uv = fragCoord / iResolution.xy;
vec2 center = vec2(radialCenterX, radialCenterY);
if (false) {
center = iMouse.xy / iResolution.xy;
}
float blurStrength = radialStrength;
const int NUM_SAMPLES = 32;
vec4 color = vec4(0.0);
float totalWeight = 0.0;
for (int i = 0; i < NUM_SAMPLES; i++)
{
if(i >= radialSamples) break; float t = float(i) / max(float(radialSamples - 1),1.0);
vec2 directionToCenter = center - uv;
vec2 sampleUV = uv + directionToCenter * t * blurStrength;
vec4 sampleColor = texture2DCv(inputImg.texture, sampleUV);
float weight = 1.0 - t * radialFalloff;
color += sampleColor * weight;
totalWeight += weight;
}
fragColor = color / totalWeight;
}
void main(){
vec4 gmGenerated=vec4(0.0);
gmGeneratedMainImage(gmGenerated,acScreenNorm*acScreenSize);
vec4 gmSource=texture2DCv(inputImg.texture,acScreenNorm);
float gmAlpha=gmClip?gmSource.a:gmGenerated.a;
vec4 gmResult=vec4(gmGenerated.rgb*gmAlpha,gmAlpha);
gl_FragColor=mix(gmSource,gmResult,gmMix);
}
